// Memes ID admin que admin-codes.json / admin-extensions.json.
const body = $input.first().json.body || {};
const adminDiscordIds = ['785223211730075709', '184008667690041345'];
const discordId = (body.discordId || '').toString();

return [{
  json: {
    docId: 'cRP1WgZQv7KmwmVrUbuEF8',
    discordId,
    isAdmin: adminDiscordIds.includes(discordId),
    action: (body.action || '').toString(),
    pityThreshold: body.pityThreshold,
    topRarityKey: body.topRarityKey,
    digMaxEnergy: body.digMaxEnergy,
    digRegenSeconds: body.digRegenSeconds,
    dailyQuestThreshold: body.dailyQuestThreshold,
    dailyQuestRewardBoosters: body.dailyQuestRewardBoosters,
    weeklyQuestThreshold: body.weeklyQuestThreshold,
    weeklyQuestRewardBoosters: body.weeklyQuestRewardBoosters,
    weeklyQuestTarget: body.weeklyQuestTarget,
    rarityId: body.rarityId,
    weight: body.weight,
    disenchantValue: body.disenchantValue,
    craftCost: body.craftCost,
    finishId: body.finishId,
    dropWeight: body.dropWeight,
    disenchantMultiplier: body.disenchantMultiplier
  }
}];

function refId(v) { return Array.isArray(v) ? v[1] : v; }
const config = $('Set Config').first().json;
const configRow = $('Get Config').all().map((i) => i.json).find((r) => r.id != null);
if (!configRow) throw new Error('Table Config vide : ajoute une ligne de parametres dans Grist.');
const rarities = $('Get Rarities').all().map((i) => i.json).filter((r) => r.id != null);

function numOr(current, incoming, min) {
  if (incoming == null || incoming === '') return current;
  const n = Number(incoming);
  if (!Number.isFinite(n) || (min != null && n < min)) throw new Error('Valeur invalide: ' + incoming);
  return n;
}

let pityThreshold = configRow.PityThreshold || 0;
if (config.pityThreshold != null && config.pityThreshold !== '') {
  const n = Number(config.pityThreshold);
  if (!Number.isFinite(n) || n < 1) throw new Error('pityThreshold invalide.');
  pityThreshold = n;
}

let topRarityId = refId(configRow.TopRarity);
if (config.topRarityKey) {
  const rarity = rarities.find((r) => r.Key === config.topRarityKey);
  if (!rarity) throw new Error('Rarete inconnue: ' + config.topRarityKey);
  topRarityId = rarity.id;
}

const digMaxEnergy = numOr(configRow.DigMaxEnergy || 5, config.digMaxEnergy, 1);
const digRegenSeconds = numOr(configRow.DigRegenSeconds || 60, config.digRegenSeconds, 5);
const dailyQuestThreshold = numOr(configRow.DailyQuestThreshold || 2, config.dailyQuestThreshold, 1);
const dailyQuestRewardBoosters = numOr(configRow.DailyQuestRewardBoosters || 2, config.dailyQuestRewardBoosters, 0);
const weeklyQuestThreshold = numOr(configRow.WeeklyQuestThreshold || 3, config.weeklyQuestThreshold, 1);
const weeklyQuestRewardBoosters = numOr(configRow.WeeklyQuestRewardBoosters || 5, config.weeklyQuestRewardBoosters, 0);
const weeklyQuestTarget = numOr(configRow.WeeklyQuestTarget || 5, config.weeklyQuestTarget, 1);

return [{ json: {
  rowId: configRow.id, pityThreshold, topRarityId,
  digMaxEnergy, digRegenSeconds,
  dailyQuestThreshold, dailyQuestRewardBoosters,
  weeklyQuestThreshold, weeklyQuestRewardBoosters, weeklyQuestTarget
} }];

function refId(v) { return Array.isArray(v) ? v[1] : v; }
const cfg = $('Set Config').first().json;
const action = cfg.action;

const rarities = $('Get Rarities').all().map((i) => i.json).filter((r) => r.id != null);
const finishes = $('Get Finishes').all().map((i) => i.json).filter((r) => r.id != null);
const configRow = $('Get Config').all().map((i) => i.json).find((r) => r.id != null);
if (!configRow) throw new Error('Table Config vide.');

let pityThreshold = configRow.PityThreshold || 0;
let topRarityId = refId(configRow.TopRarity);
let digMaxEnergy = configRow.DigMaxEnergy || 5;
let digRegenSeconds = configRow.DigRegenSeconds || 60;
let dailyQuestThreshold = configRow.DailyQuestThreshold || 2;
let dailyQuestRewardBoosters = configRow.DailyQuestRewardBoosters || 2;
let weeklyQuestThreshold = configRow.WeeklyQuestThreshold || 3;
let weeklyQuestRewardBoosters = configRow.WeeklyQuestRewardBoosters || 5;
let weeklyQuestTarget = configRow.WeeklyQuestTarget || 5;

if (action === 'set') {
  const built = $('Build Update').first().json;
  pityThreshold = built.pityThreshold;
  topRarityId = built.topRarityId;
  digMaxEnergy = built.digMaxEnergy;
  digRegenSeconds = built.digRegenSeconds;
  dailyQuestThreshold = built.dailyQuestThreshold;
  dailyQuestRewardBoosters = built.dailyQuestRewardBoosters;
  weeklyQuestThreshold = built.weeklyQuestThreshold;
  weeklyQuestRewardBoosters = built.weeklyQuestRewardBoosters;
  weeklyQuestTarget = built.weeklyQuestTarget;
}

let raritiesOut = rarities;
if (action === 'updateRarity') {
  const built = $('Build Rarity Update').first().json;
  raritiesOut = rarities.map((r) => r.id === built.rowId ? { ...r, Weight: built.weight, DisenchantValue: built.disenchantValue, CraftCost: built.craftCost } : r);
}

let finishesOut = finishes;
if (action === 'updateFinish') {
  const built = $('Build Finish Update').first().json;
  finishesOut = finishes.map((f) => f.id === built.rowId ? { ...f, DropWeight: built.dropWeight, DisenchantMultiplier: built.disenchantMultiplier } : f);
}

const topRarity = rarities.find((r) => r.id === topRarityId);

return [{ json: {
  pityThreshold,
  topRarity: topRarity ? { id: topRarity.id, key: topRarity.Key, name: topRarity.Name } : null,
  digMaxEnergy, digRegenSeconds,
  dailyQuestThreshold, dailyQuestRewardBoosters,
  weeklyQuestThreshold, weeklyQuestRewardBoosters, weeklyQuestTarget,
  rarities: raritiesOut.sort((a, b) => (a.SortOrder || 0) - (b.SortOrder || 0)).map((r) => ({ id: r.id, key: r.Key, name: r.Name, weight: r.Weight || 0, disenchantValue: r.DisenchantValue || 0, craftCost: r.CraftCost || 0 })),
  finishes: finishesOut.map((f) => ({ id: f.id, key: f.Key, name: f.Name, dropWeight: f.DropWeight || 0, disenchantMultiplier: f.DisenchantMultiplier != null ? f.DisenchantMultiplier : 1 }))
} }];

const config = $('Set Config').first().json;
const rarities = $('Get Rarities').all().map((i) => i.json).filter((r) => r.id != null);
const rarityId = Number(config.rarityId);
const rarity = rarities.find((r) => r.id === rarityId);
if (!rarity) throw new Error('Rarete introuvable: ' + config.rarityId);

function numOr(current, incoming, min) {
  if (incoming == null || incoming === '') return current;
  const n = Number(incoming);
  if (!Number.isFinite(n) || (min != null && n < min)) throw new Error('Valeur invalide: ' + incoming);
  return n;
}

const weight = numOr(rarity.Weight || 0, config.weight, 0);
const disenchantValue = numOr(rarity.DisenchantValue || 0, config.disenchantValue, 0);
const craftCost = numOr(rarity.CraftCost || 0, config.craftCost, 0);

return [{ json: { rowId: rarityId, weight, disenchantValue, craftCost } }];

const config = $('Set Config').first().json;
const finishes = $('Get Finishes').all().map((i) => i.json).filter((r) => r.id != null);
const finishId = Number(config.finishId);
const finish = finishes.find((f) => f.id === finishId);
if (!finish) throw new Error('Finition introuvable: ' + config.finishId);

function numOr(current, incoming, min) {
  if (incoming == null || incoming === '') return current;
  const n = Number(incoming);
  if (!Number.isFinite(n) || (min != null && n < min)) throw new Error('Valeur invalide: ' + incoming);
  return n;
}

const dropWeight = numOr(finish.DropWeight || 0, config.dropWeight, 0);
const disenchantMultiplier = numOr(finish.DisenchantMultiplier != null ? finish.DisenchantMultiplier : 1, config.disenchantMultiplier, 0);

return [{ json: { rowId: finishId, dropWeight, disenchantMultiplier } }];
